#define main preserved_native_main
#include "../../particles-cuda/main.cu"
#undef main
#include "../../particles-cuda/particles.cu"
#include "../../particles-cuda/bitonicSort.cu"
#include "../study_reference_cpu.h"
#include "../study_validation.h"
int main(int argc,char**argv){int steps=atoi(argv[1]);constexpr size_t N=16384,C=262144;auto pr=readBlob("study_input_pos_f32.bin"),vr=readBlob("study_input_vel_f32.bin");char expectedName[100];snprintf(expectedName,100,"study_expected_step%d_f64.bin",steps);auto er=readBlob(expectedName);std::vector<double>cpu(er.size()/8);memcpy(cpu.data(),er.data(),er.size());simParams_t p=studyParams();float4 *pos,*vel,*rpos,*rvel;unsigned *keys,*index,*starts,*ends;cudaMalloc(&pos,N*16);cudaMalloc(&vel,N*16);cudaMalloc(&rpos,N*16);cudaMalloc(&rvel,N*16);cudaMalloc(&keys,N*4);cudaMalloc(&index,N*4);cudaMalloc(&starts,C*4);cudaMalloc(&ends,C*4);auto reset=[&](){cudaMemcpy(pos,pr.data(),N*16,cudaMemcpyHostToDevice);cudaMemcpy(vel,vr.data(),N*16,cudaMemcpyHostToDevice);cudaMemset(rpos,0,N*16);cudaMemset(rvel,0,N*16);cudaMemset(ends,255,C*4);};auto execute=[&](){for(int step=0;step<steps;step++){integrateSystem(pos,vel,p,timestep,N);calcHash(keys,index,pos,p,N);bitonicSort(keys,index,keys,index,1,N,0);findCellBoundsAndReorder(starts,ends,rpos,rvel,keys,index,pos,vel,N,C);collide(vel,rpos,rvel,index,starts,ends,p,N,C);}};std::vector<double>prefix;for(auto*raw:{&pr,&vr})for(size_t i=0;i<raw->size()/4;i++){float a;memcpy(&a,raw->data()+4*i,4);prefix.push_back(a);}auto pv=parameterValues(p);prefix.insert(prefix.end(),pv.begin(),pv.end());prefix.push_back(timestep);prefix.push_back(steps);std::vector<float4>hp(N),hv(N),hrp(N),hrv(N);std::vector<unsigned>hk(N),hi(N),hs(C),he(C);bool allok=true;std::vector<double>allStates;reset();cudaDeviceSynchronize();for(int trial=1;trial<=8;trial++){integrateSystem(pos,vel,p,timestep,N);calcHash(keys,index,pos,p,N);bitonicSort(keys,index,keys,index,1,N,0);findCellBoundsAndReorder(starts,ends,rpos,rvel,keys,index,pos,vel,N,C);collide(vel,rpos,rvel,index,starts,ends,p,N,C);auto status=cudaDeviceSynchronize();cudaMemcpy(hp.data(),pos,N*16,cudaMemcpyDeviceToHost);cudaMemcpy(hv.data(),vel,N*16,cudaMemcpyDeviceToHost);cudaMemcpy(hrp.data(),rpos,N*16,cudaMemcpyDeviceToHost);cudaMemcpy(hrv.data(),rvel,N*16,cudaMemcpyDeviceToHost);cudaMemcpy(hk.data(),keys,N*4,cudaMemcpyDeviceToHost);cudaMemcpy(hi.data(),index,N*4,cudaMemcpyDeviceToHost);cudaMemcpy(hs.data(),starts,C*4,cudaMemcpyDeviceToHost);cudaMemcpy(he.data(),ends,C*4,cudaMemcpyDeviceToHost);auto check=checkState(hp,hv,hrp,hrv,hk,hi,hs,he,cpu,p);bool ok=status==cudaSuccess&&check.ok;allok&=ok;std::vector<double>got=prefix;got.insert(got.end(),check.values.begin(),check.values.end());allStates.insert(allStates.end(),got.begin(),got.end());if(trial==8){FILE*f=fopen("all_eight_states.bin","wb");fwrite(allStates.data(),8,allStates.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":1,\"time_seconds\":null,\"correct\":false,\"diagnostic_only\":true,\"excluded_from_primary\":true,\"physical_steps\":8,\"saved_state_count\":8,\"state_stride_values\":%zu,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"output_artifact\":{\"path\":\"all_eight_states.bin\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",got.size(),got.size(),check.absolute,check.relative,allStates.size());}}return 1;}